#include "stdafx.h"#include "HcdElementBase.h"#include "Calculon.h"struct SMATH_P{#include "PrivateVars/MATH.h"};using namespace ns_HcdTranslator;class KMATH : public KHcdElementBase  , protected SMATH_P  , protected KCalculon{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void OnFilledProjectSettings();  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _MATH("MATH", KMATH::Create);IHcdElement *KMATH::Create(){  return new KMATH;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KMATH, 12 )void KMATH::InitParm(){#include "PrivateVars/MATH.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KMATH::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KMATH::OnFilledProjectSettings(){  KHcdTranslator trans;  trans.ParseText( Equation );  tOPCont_ Ops;  tVarCont_ Vars;  trans.GetCodeOPs( Ops, Vars );  m_nOps = Ops.size();  if( m_nOps )  {    m_pOps = (SOPElement*)KMemoryServiceHCD::Instance().NewMem( m_nOps * sizeof(*m_pOps) );    CopyMemory( m_pOps, &Ops.at(0), m_nOps * sizeof(*m_pOps) );  }  m_nVars = Vars.size();  if( m_nVars )  {    m_pVars = (SCalcVar*)KMemoryServiceHCD::Instance().NewMem( m_nVars * sizeof(*m_pVars) );    for( size_t i=0; i<m_nVars; ++i )      m_pVars[i] = Vars[i];  }  for( size_t i=0; i<m_nVars; ++i )  {    if( KVar::Reference != m_pVars[i].Type )    {      if( KVar::LocalValue == m_pVars[i].Type )      {        BYTE *pMem = __super::GetField( (LPSTR)(LPCSTR)m_pVars[i].szName, &m_pVars[i].vType, &m_pVars[i].vSize );        if( pMem )        {          m_pVars[i].Type = KVar::Reference;          m_pVars[i].pMem = pMem;        }      }      continue;    }    ASSD(0);  }}void KMATH::StepCalc( SStepCalcParams &params ){  OUT = Calc();}